import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

/**
 * Unit tests for DoubleSerializer.serializeWithType
 */
public class DoubleSerializer_serializeWithType_TriageGen2Test {

    private NumberSerializers.DoubleSerializer doubleSerializer;
    private JsonGenerator jsonGenerator;
    private SerializerProvider serializerProvider;
    private TypeSerializer typeSerializer;

    @Before
    public void setUp() {
        // We use a spy because we want to verify that serialize() is called 
        // when serializeWithType() is invoked, as serializeWithType calls serialize.
        doubleSerializer = spy(new NumberSerializers.DoubleSerializer());
        jsonGenerator = mock(JsonGenerator.class);
        serializerProvider = mock(SerializerProvider.class);
        typeSerializer = mock(TypeSerializer.class);
    }

    @Test
    public void testSerializeWithType_CallsSerialize() throws IOException {
        // Arrange
        Object value = 123.45d;

        // Act
        doubleSerializer.serializeWithType(value, jsonGenerator, serializerProvider, typeSerializer);

        // Assert
        // The implementation of serializeWithType is: serialize(value, gen, provider);
        // We verify that the serialize method was called exactly once with the correct arguments.
        verify(doubleSerializer, times(1)).serialize(value, jsonGenerator, serializerProvider);

        // Verify that typeSerializer was NOT used (as per the comment "no type info, just regular serialization")
        verifyNoInteractions(typeSerializer);
    }

    @Test(expected = IOException.class)
    public void testSerializeWithType_ThrowsIOExceptionWhenSerializeFails() throws IOException {
        // Arrange
        Object value = 123.45d;
        // Force the serialize method to throw an IOException
        doThrow(new IOException("Simulated IO error")).when(doubleSerializer)
                .serialize(any(), any(), any());

        // Act
        doubleSerializer.serializeWithType(value, jsonGenerator, serializerProvider, typeSerializer);

        // Assert: Expected IOException
    }

    @Test
    public void testSerializeWithType_HandlesNullValue() throws IOException {
        // Arrange
        Object value = null;

        // Act
        doubleSerializer.serializeWithType(value, jsonGenerator, serializerProvider, typeSerializer);

        // Assert
        verify(doubleSerializer, times(1)).serialize(null, jsonGenerator, serializerProvider);
    }
}
